const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo(function(res) { resolve(res); }, function(err) { reject(err); });
  });
}

function maskLandsatL2(img) {
  var qa = img.select('QA_PIXEL');
  var clear = qa.bitwiseAnd(1 << 1).eq(0) // Dilated cloud
    .and(qa.bitwiseAnd(1 << 2).eq(0))     // Cirrus
    .and(qa.bitwiseAnd(1 << 3).eq(0))     // Cloud
    .and(qa.bitwiseAnd(1 << 4).eq(0));    // Cloud shadow
  var sr = img.select('SR_B.*').multiply(0.0000275).add(-0.2);
  var imgScaled = img.addBands(sr, null, true).updateMask(clear);
  var green = imgScaled.select(['SR_B3', 'SR_B2']).reduce(ee.Reducer.firstNonNull());
  var swir1 = imgScaled.select(['SR_B6', 'SR_B5']).reduce(ee.Reducer.firstNonNull());
  var mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('mndwi');
  return imgScaled.addBands(mndwi);
}

async function summarizeJRC(year, geom) {
  var start = ee.Date.fromYMD(year, 4, 1);
  var end = start.advance(1, 'month');
  var col = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory')
              .filterDate(start, end)
              .filterBounds(geom);
  var size = await getInfoAsync(col.size());
  if (!size || size === 0) return { status: 'missing', sizeJRC: 0 };

  var img = ee.Image(col.first());
  var water = img.select('water');
  var obsMask = water.gt(0).selfMask().rename('obs');     // observed pixels (water or not)
  var watMask = water.eq(2).selfMask().rename('wat');     // water pixels

  var obsCount = ee.Image(1).updateMask(obsMask).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom, scale: 1000, maxPixels: 1e9
  }).get('constant');
  var obsCountVal = await getInfoAsync(obsCount);
  if (!obsCountVal || obsCountVal === 0) {
    return { status: 'no_valid_pixels', sizeJRC: size };
  }

  var waterAreaM2 = watMask.multiply(ee.Image.pixelArea()).rename('wa').reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom, scale: 1000, maxPixels: 1e9
  }).get('wa');
  var waterAreaM2Val = await getInfoAsync(waterAreaM2);
  var areaKm2 = (waterAreaM2Val == null ? 0 : waterAreaM2Val) / 1e6;

  return { status: 'ok', sizeJRC: size, obsCount: obsCountVal, areaKm2: areaKm2 };
}

async function summarizeLandsat(year, geom) {
  var start = ee.Date.fromYMD(year, 4, 1);
  var end = start.advance(1, 'month');
  var colId = (year < 1999) ? 'LANDSAT/LT05/C02/T1_L2'
            : (year >= 2013) ? 'LANDSAT/LC08/C02/T1_L2'
            : 'LANDSAT/LE07/C02/T1_L2';

  var col = ee.ImageCollection(colId).filterDate(start, end).filterBounds(geom).map(maskLandsatL2);
  var size = await getInfoAsync(col.size());
  if (!size || size === 0) {
    // Broaden to Mar 1 - Jun 1 as recovery
    var colBroad = ee.ImageCollection(colId).filterDate(ee.Date.fromYMD(year,3,1), ee.Date.fromYMD(year,6,1))
                    .filterBounds(geom).map(maskLandsatL2);
    var sizeB = await getInfoAsync(colBroad.size());
    if (!sizeB || sizeB === 0) return { status: 'missing', lsSize: 0 };
    col = colBroad;
    size = sizeB;
  }

  var mndwiMed = col.select('mndwi').median().clip(geom);
  var validCount = mndwiMed.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom, scale: 1000, maxPixels: 1e9
  }).get('mndwi');
  var validCountVal = await getInfoAsync(validCount);
  if (!validCountVal || validCountVal === 0) {
    return { status: 'no_valid_pixels', lsSize: size };
  }

  var waterMask = mndwiMed.gt(0.3).selfMask();
  var waterAreaM2 = waterMask.multiply(ee.Image.pixelArea()).rename('wa').reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom, scale: 1000, maxPixels: 1e9
  }).get('wa');
  var waterAreaM2Val = await getInfoAsync(waterAreaM2);
  var areaKm2 = (waterAreaM2Val == null ? 0 : waterAreaM2Val) / 1e6;

  return { status: 'ok', lsSize: size, obsCount: validCountVal, areaKm2: areaKm2 };
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var geom = ee.Geometry.Rectangle([12.1, 51.1, 12.6, 51.4], null, false);
    var regionAreaKm2 = (await getInfoAsync(geom.area(1))).valueOf() / 1e6;

    // 2. Get JRC summaries; fallback to Landsat if missing
    var jrc1987 = await summarizeJRC(1987, geom);
    var jrc2020 = await summarizeJRC(2020, geom);

    console.log(`Region km2: ${regionAreaKm2.toFixed(1)}`);
    console.log(`JRC 1987 Apr Images: ${jrc1987.sizeJRC || 0}`);
    console.log(`JRC 2020 Apr Images: ${jrc2020.sizeJRC || 0}`);

    let s1987, s2020, usedJRC1987 = false, usedJRC2020 = false;

    if (jrc1987.status === 'ok') { s1987 = jrc1987; usedJRC1987 = true; }
    else if (jrc1987.status === 'no_valid_pixels') { console.log('1987: JRC has 0 valid pixels.'); }
    else { console.log('1987: JRC missing, trying Landsat.'); }

    if (jrc2020.status === 'ok') { s2020 = jrc2020; usedJRC2020 = true; }
    else if (jrc2020.status === 'no_valid_pixels') { console.log('2020: JRC has 0 valid pixels.'); }
    else { console.log('2020: JRC missing, trying Landsat.'); }

    if (!s1987) {
      var ls1987 = await summarizeLandsat(1987, geom);
      if (ls1987.status === 'missing') { console.log('1987 Landsat: 0 images (even after widening).'); console.log('C1'); return; }
      if (ls1987.status === 'no_valid_pixels') { console.log('1987 Landsat: No valid pixels after masking.'); console.log('C2'); return; }
      s1987 = ls1987;
    }

    if (!s2020) {
      var ls2020 = await summarizeLandsat(2020, geom);
      if (ls2020.status === 'missing') { console.log('2020 Landsat: 0 images (even after widening).'); console.log('C1'); return; }
      if (ls2020.status === 'no_valid_pixels') { console.log('2020 Landsat: No valid pixels after masking.'); console.log('C2'); return; }
      s2020 = ls2020;
    }

    // 3. Validation of results
    function invalidArea(a) {
      return (a == null) || isNaN(a) || a < 0 || a > regionAreaKm2 * 1.05;
    }
    if (invalidArea(s1987.areaKm2) || invalidArea(s2020.areaKm2)) {
      console.log('Invalid area result (None/NaN or out of range).');
      console.log('C3'); return;
    }

    // 4. Report concise stats
    console.log(`1987 Apr Water km2: ${s1987.areaKm2.toFixed(2)} (Obs: ${s1987.obsCount}) [${usedJRC1987 ? 'JRC' : 'Landsat'}]`);
    console.log(`2020 Apr Water km2: ${s2020.areaKm2.toFixed(2)} (Obs: ${s2020.obsCount}) [${usedJRC2020 ? 'JRC' : 'Landsat'}]`);
    var change = s2020.areaKm2 - s1987.areaKm2;
    console.log(`Change km2 (2020-1987): ${change.toFixed(2)}`);

    // 5. Final Answer
    const epsilon = 0.1; // km2 threshold to avoid noise
    if (change > epsilon) console.log('A');
    else console.log('B');

  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
